package helpers

import (
	"context"
	_ "embed"
	"fmt"
	"math/big"
	"strings"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/core/types"
	"github.com/ethereum/go-ethereum/crypto"

	"github.com/ethera-labs/dome/internal/accounts"
	"github.com/ethera-labs/dome/internal/transactions"
)

// MintableTokenABI is the minimal ABI for the test-only mintable ERC-20.
// Constructor: `(string name, string symbol, uint8 decimals_)`.
// Lifted verbatim from scripts/l1-to-l2-new-token.ts.
const MintableTokenABI = `[
	{"type":"constructor","inputs":[{"name":"name","type":"string"},{"name":"symbol","type":"string"},{"name":"decimals_","type":"uint8"}],"stateMutability":"nonpayable"},
	{"type":"function","name":"name","inputs":[],"outputs":[{"type":"string"}],"stateMutability":"view"},
	{"type":"function","name":"symbol","inputs":[],"outputs":[{"type":"string"}],"stateMutability":"view"},
	{"type":"function","name":"decimals","inputs":[],"outputs":[{"type":"uint8"}],"stateMutability":"view"},
	{"type":"function","name":"balanceOf","inputs":[{"name":"owner","type":"address"}],"outputs":[{"type":"uint256"}],"stateMutability":"view"},
	{"type":"function","name":"allowance","inputs":[{"name":"owner","type":"address"},{"name":"spender","type":"address"}],"outputs":[{"type":"uint256"}],"stateMutability":"view"},
	{"type":"function","name":"approve","inputs":[{"name":"spender","type":"address"},{"name":"amount","type":"uint256"}],"outputs":[{"type":"bool"}],"stateMutability":"nonpayable"},
	{"type":"function","name":"mint","inputs":[{"name":"to","type":"address"},{"name":"amount","type":"uint256"}],"outputs":[],"stateMutability":"nonpayable"},
	{"type":"function","name":"transfer","inputs":[{"name":"to","type":"address"},{"name":"value","type":"uint256"}],"outputs":[{"type":"bool"}],"stateMutability":"nonpayable"},
	{"type":"function","name":"transferFrom","inputs":[{"name":"from","type":"address"},{"name":"to","type":"address"},{"name":"value","type":"uint256"}],"outputs":[{"type":"bool"}],"stateMutability":"nonpayable"}
]`

// MintableTokenBytecode is the deploy bytecode for the test mintable ERC-20,
// lifted from scripts/l1-to-l2-new-token.ts (Solidity 0.8.20, optimizer on).
const MintableTokenBytecode = ""

// ParseMintableTokenABI returns the parsed MintableToken ABI for callers that
// also need it for read/write calls after deploy.
func ParseMintableTokenABI() (abi.ABI, error) {
	return abi.JSON(strings.NewReader(MintableTokenABI))
}

// DeployMintableToken deploys a fresh MintableToken on the account's rollup and
// returns the contract address once the deploy tx is mined.
func DeployMintableToken(
	ctx context.Context,
	ac *accounts.Account,
	name string,
	symbol string,
	decimals uint8,
) (common.Address, *types.Transaction, error) {
	parsedABI, err := ParseMintableTokenABI()
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("parse mintable abi: %w", err)
	}

	constructorArgs, err := parsedABI.Pack("", name, symbol, decimals)
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("pack constructor: %w", err)
	}

	bytecode, err := hexutil.Decode(MintableTokenBytecode)
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("decode bytecode: %w", err)
	}
	deployData := append(bytecode, constructorArgs...)

	// Contract creation tx: to == nil. CreateTransaction wants a `To`, so we use
	// the lower-level types.DynamicFeeTx via the existing helper but with a
	// zero-address To and skip the SendTransaction layer.
	nonce, err := ac.GetNonce(ctx)
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("nonce: %w", err)
	}
	tx := types.NewTx(&types.DynamicFeeTx{
		ChainID:   ac.GetRollup().ChainID(),
		Nonce:     nonce,
		To:        nil,
		Gas:       3_000_000,
		GasTipCap: GasTipCap,
		GasFeeCap: GasFeeCap,
		Value:     big.NewInt(0),
		Data:      deployData,
	})
	signed, err := types.SignTx(tx, types.NewLondonSigner(ac.GetRollup().ChainID()), ac.GetPrivateKey())
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("sign deploy: %w", err)
	}
	if _, err := transactions.SendTransaction(ctx, signed, ac.GetRollup().RPCURL()); err != nil {
		return common.Address{}, nil, fmt.Errorf("send deploy: %w", err)
	}
	_, receipt, err := transactions.GetTransactionDetails(ctx, signed.Hash(), ac.GetRollup())
	if err != nil {
		return common.Address{}, nil, fmt.Errorf("get deploy receipt: %w", err)
	}
	if receipt.Status != types.ReceiptStatusSuccessful {
		return common.Address{}, nil, fmt.Errorf("deploy failed: %s", signed.Hash().Hex())
	}
	// receipt.ContractAddress holds the deployed address. Fallback to
	// computing CREATE address from sender+nonce in case the RPC didn't fill it.
	addr := receipt.ContractAddress
	if addr == (common.Address{}) {
		addr = crypto.CreateAddress(ac.GetAddress(), nonce)
	}
	return addr, signed, nil
}
